func TestWeatherAndEffortFormatting(t *testing.T) {
	if effortTime(59.6) != "1:00" || effortTime(3725) != "1:02:05" {
		t.Error("effortTime")
	}
	v := newWeatherView(store.Weather{TempMinC: 14.6, TempMaxC: 15.2, ApparentC: 15, WindKmh: 5, WindDirDeg: 350, GustKmh: 8, Code: 0})
	if v.Temp != "15 °C" || v.Wind != "5 km/h aus N" || v.Precip != "" || v.Label != "Klar" {
		t.Errorf("weather %+v", v)
	}
	if v := newWeatherView(store.Weather{TempMinC: 10.4, TempMaxC: 10.5, ApparentC: 10.2}); v.Temp != "10 °C" {
		t.Errorf("halves must not produce a range: %q", v.Temp)
	}
	val, detail := effortValue(store.Effort{Group: "run", Kind: store.EffortDistance, Key: 5000, Value: 1500})
	if val != "25:00" || detail != "5:00 /km" {
		t.Errorf("run effort %q %q", val, detail)
	}
	val, detail = effortValue(store.Effort{Kind: store.EffortClimb, Value: 320, Extra: 4000})
	if val != "320 Hm" || detail != "4,0 km · ⌀ 8,0 %" {
		t.Errorf("climb %q %q", val, detail)
	}
}
